Translate("deDE", "duskwood", {
	title = "Dämmerwald",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Dämmerwald ist ein Wald der endlosen Nacht im Süden des {link:kingdom-of-stormwind}Königreichs Stormwind{/link}. Seine alten Bäume schließen sich über den Köpfen, sodass kein echter Tag je den Boden erreicht. Die Toten wandeln auf seinen Friedhöfen, Wolfsmenschen streifen durch seine Haine, und Spinnen nisten an seinen Flüssen. Im Osten liegt der Ort {link:darkshire}Dunkelhain{/link}, wo die Letzten, die nicht geflohen sind, ihre Fackeln brennen lassen und ihre Türen verriegeln.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Der Wald war nicht immer so. Wer ihn vor den Kriegen kannte, erinnert sich an grüne Wälder, geschäftige Höfe und ein Dorf, das seither den Namen {link:darkshire}Dunkelhain{/link} trägt. Im {link:first-war}Ersten Krieg{/link} brannte die {link:horde}Horde{/link} diese Wälder nieder, wie sie {link:elwynn-forest}Elwynn{/link} niederbrannte. Die Höfe wurden danach wieder aufgebaut. Dann, in den Jahren, als die Männer des Königreichs nach Norden in den {link:third-war}Dritten Krieg{/link} zogen, kam etwas Schlimmeres. Eine Magie, die niemand in Dunkelhain benennen kann, sickerte in das Land. Die Blätter verdunkelten sich, die Gräber öffneten sich, und seither lebt der Wald in der Dämmerung.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Der Dämmerwald steht allein. Als die Dunkelheit kam, rief {link:stormwind-city}Stormwind{/link} seine Wachen heim und schickte sie nicht zurück. Der Ort stellte eine eigene Miliz auf, die {link:the-night-watch}Nachtwache{/link}, unter {link:commander-althea-ebonlocke}Kommandantin Althea Ebonlocke{/link}, und seither hält sie das Herz des Waldes mit zu wenigen Schwertern. Die Wache ist nicht die einzige Sorge um den Frieden Dunkelhains. Die Lords von Stormwind heben die Urteile seines Rates auf, und einer seiner Ratsherren spricht offen davon, mit der Krone zu brechen. Jenseits der Mauern haben die {link:nightbane-worgen}Nightbane-Worgen{/link} den Süden eingenommen, die Toten halten {link:raven-hill}Rabenflucht{/link}, {link:ogres}Oger{/link} halten {link:razorfen-downs}die Hügel{/link} im Süden, und die {link:defias-brotherhood}Bruderschaft der Defias{/link} nutzt die Höfe im Westen als Weg für ihre Pläne. {link:dark-riders}Dunkle Reiter{/link} kommen im Osten aus dem {link:deadwind-pass}Gebirgspass der Totenwinde{/link}, und niemand weiß, was sie wollen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Das Volk von {link:darkshire}Dunkelhain{/link}.{/b} Händler, Schmiede, eine Seherin, ein Geschichtsschreiber und ein Rat, der noch immer im Rathaus tagt. Die meisten haben jemanden an den Wald verloren.
• {b}{link:the-night-watch}Die Nachtwache{/link}.{/b} Wächter hüten die Tore des Ortes, den Platz und eine Handvoll einsamer Posten an den Straßen.
• {b}Die {link:carevin-family}Familie Carevin{/link}.{/b} Ein Haus von Jägern, die ihren eigenen Krieg gegen Dämonen und Untote führen.
• {b}Die Toten.{/b} Skelette, Ghule und ruhelose Geister füllen den {link:raven-hill-cemetery}Friedhof von Rabenflucht{/link} und die Stillen Gärten.
• {b}Die {link:nightbane-worgen}Nightbane{/link}.{/b} Worgen, die wie aus dem Nichts erschienen und nun den Süden des Waldes halten.
• {b}Die {link:ogres}Oger{/link}.{/b} Der Clan Splinter Fist hält den {link:vul-gol-ogre-mound}Ogerhort Vul'Gol{/link}.
• {b}Die Verlassenen.{/b} Eine kleine Expedition der {link:forsaken}Verlassenen{/link} verbirgt sich im {link:beggar-s-haunt}Bettlerschlupfwinkel{/link} im äußersten Osten.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der alte Wald.{/b} Vor den Kriegen war der Wald grün, und seine Höfe und Dörfer blühten.
• {b}Der Erste Krieg.{/b} Die {link:horde}Horde{/link} brannte die Wälder auf ihrem Weg nach {link:stormwind-city}Stormwind{/link} nieder.
• {b}Die Verdunkelung.{/b} In den Jahren des Dritten Krieges ergriff eine üble Magie den Wald. {link:raven-hill}Rabenflucht{/link} fiel und mit ihm sein Volk. Stormwind zog seine Wachen ab, und {link:darkshire}Dunkelhain{/link} stellte an ihrer Stelle die {link:the-night-watch}Nachtwache{/link} auf.
• {b}Die Gegenwart.{/b} Dunkelhain hält stand, aber nur knapp, und seine Leute fragen sich allmählich, ob das Königreich sie noch zu den Seinen zählt.]=],
		},
		{
			title = "Überlieferungen des Waldes",
			text = [=[• Die Kinder von {link:darkshire}Dunkelhain{/link} wachsen mit der Geschichte eines gütigen Alchemisten auf, den man den {link:abercrombie}Einbalsamierer{/link} nennt und der aus Trauer um seine tote Frau wahnsinnig wurde.
• Den Namen {link:stalvan-mistmantle}Stalvan Mistmantle{/link} spricht man im Ort nur flüsternd aus.
• Wer sich in den dunklen Wäldern verirrt, erzählt manchmal, ein Schatten habe ihn zurück zur Straße geführt.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage verzeichnet, was den Dämmerwald zuerst verdunkelte, noch das Jahr, in dem es geschah.]=],
		},
	},
})

Translate("deDE", "darkshire", {
	title = "Dunkelhain",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dunkelhain ist der letzte echte Ort des Dämmerwalds, ein Knäuel von Holzhäusern um einen Platz im Osten des Waldes. {link:the-night-watch}Die Nachtwache{/link} hütet seine Tore. Der Bürgermeister, {link:lord-ello-ebonlocke}Lord Ello Ebonlocke{/link}, hält im Rathaus Hof mit seinem Rat und seinem Schreiber. Reisende trinken in der Scarlet Raven Tavern, wo der Koch Kuchen zweifelhafter Herkunft serviert. Eine Seherin legt in einem Haus am Platz die Karten, und ein Geschichtsschreiber hütet eine Bibliothek, die jedes Jahr dünner wird. Die Leute hier lassen ihre Lampen die ganze Nacht brennen.]=],
		},
	},
})

Translate("deDE", "raven-hill", {
	title = "Rabenflucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rabenflucht war einst ein stolzes Dorf im Westen des Dämmerwalds. Heute ist es ein Geisterdorf. Seine Häuser stehen leer, und seine Bewohner liegen auf dem großen Friedhof im Norden. Nur wenige Aufzeichnungen über das Dorf überstanden seinen Fall, und selbst der Geschichtsschreiber von {link:darkshire}Dunkelhain{/link} weiß wenig darüber zu sagen. Neuerdings hören die Leute des Ortes von Schatten, die sich zwischen den Häusern bewegen, und von einem Licht in einem Fenster. Der Spuk war nur ein verängstigter Mann in seinem Versteck. Die Geister der {link:the-valor-family}Familie Valor{/link}, die das Dorf einst verteidigte, sind eine andere Sache.]=],
		},
	},
})

Translate("deDE", "raven-hill-cemetery", {
	title = "Friedhof von Rabenflucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Friedhof von Rabenflucht erstreckt sich über den Nordwesten des Dämmerwalds, so weit, dass er nun das Land ringsum beherrscht. Die Skelette seiner Toten marschieren in Reihen zwischen den Steinen, und Ghule verseuchen seine Mausoleen. {link:the-night-watch}Die Nachtwache{/link} hat immer wieder Freiwillige hierher geschickt, und noch immer kehren die Toten zurück. Hier fand der Ritter {link:mor-ladim}Morgan Ladimore{/link} die Gräber seiner Familie, und hier fand man später sein eigenes Grab leer. In einer Hütte an seinem Nordrand lebt ein alter Einsiedler. Nahe seiner Tür liegt das Grab einer Frau namens {link:eliza}Eliza{/link}.]=],
		},
	},
})

Translate("deDE", "forlorn-rowe", {
	title = "Das verlassene Gut",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das verlassene Gut ist ein Haus auf einem Hügel über dem {link:raven-hill-cemetery}Friedhof von Rabenflucht{/link}. Es ist der Unterschlupf des Nekromanten {link:morbent-fel}Morbent Fel{/link}, und hierher kommen die dunklen Reiter aus dem {link:deadwind-pass}Gebirgspass der Totenwinde{/link}, um mit ihm zu sprechen. Die Skelette, die den Hügel bewachen, sind seine Diener. Eine Zeit lang kaufte er Leichen von dem Grabräuber {link:dextren-ward}Dextren Ward{/link}, bis Ward gefasst und ins {link:the-stockade}Verlies von Stormwind{/link} gebracht wurde. {link:sven-yorgen}Sven Yorgen{/link} beobachtet dieses Haus von seinem Lager im Westen aus und wartet auf den Tag, an dem es verstummt.]=],
		},
	},
})

Translate("deDE", "manor-mistmantle", {
	title = "Anwesen der Mistmantles",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Anwesen der Mistmantles steht ein kurzes Stück nördlich von {link:darkshire}Dunkelhain{/link}, ein einsames Haus unter den schwarzen Bäumen. Sein Herr ist {link:stalvan-mistmantle}Stalvan Mistmantle{/link}, einst ein Lehrer von Kindern, dessen Name heute für Mord steht. Er kam aus dem {link:silverpine-forest}Silberwald{/link}, weit im Norden, und unterzeichnete seine Briefe einst mit dem Namen seiner Heimat. {link:the-night-watch}Die Nachtwache{/link} verdächtigte ihn lange alter Morde, doch sie konnte nichts beweisen. Die Leute des Ortes machen einen weiten Bogen um das Haus, und wer nachts daran vorbeikommt, verweilt nicht.]=],
		},
	},
})

Translate("deDE", "roland-s-doom", {
	title = "Rolands Verdammnis",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rolands Verdammnis ist eine Mine im Süden des Dämmerwalds. In ihren Stollen war die Arbeit schon immer hart, aber nicht tödlich, bis ein Bergmann den Schaft einer seltsamen Sense aus einem Geröllhaufen zog. In jener Nacht kamen die Worgen aus dem Fels selbst. Die Hälfte der Bergleute starb in den ersten Augenblicken. Die {link:nightbane-worgen}Nightbane{/link} halten die Mine noch immer, und ihre Feuer sind von weitem zu sehen. Hier fand man die ersten Worgen des Dämmerwalds, und hier endet die Spur der {red:scythe-of-elune}Sense von Elune{/red}.]=],
		},
	},
})

Translate("deDE", "addle-s-stead", {
	title = "Addles Siedlung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Addles Siedlung ist ein verlassener Hof im Südwesten des Dämmerwalds, südlich der Straße aus {link:westfall}Westfall{/link}. Seine Bauern sind fort. Die {link:defias-brotherhood}Bruderschaft der Defias{/link} hat ihn zu einem Treffpunkt gemacht, und ihre Nachtklingen und Verzauberer halten zwischen den verwüsteten Feldern Wache. Vor einiger Zeit sah die {link:the-night-watch}Nachtwache{/link} dort eine Versammlung von Agenten der Defias, groß genug, um zu vermuten, dass etwas Wichtiges durchgekommen war. Man sagt, der Geist einer Wache von {link:raven-hill}Rabenflucht{/link} wandle noch immer über seine Felder.]=],
		},
	},
})

Translate("deDE", "the-rotting-orchard", {
	title = "Der verlassene Obstgarten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der verlassene Obstgarten liegt südwestlich von {link:darkshire}Dunkelhain{/link}. Seine Bäume stehen noch in ihren Reihen, doch ihre Früchte sind längst gefallen und verfault. Die {link:nightbane-worgen}Nightbane-Worgen{/link} haben ihn überrannt. Ihre Schattenweber und Dunkelläufer jagen zwischen den Stämmen, und hierher schicken die Jäger der {link:carevin-family}Familie Carevin{/link} jene, die sich ihnen anschließen wollen. Ihr Jäger {link:calor}Calor{/link} hat erfahren, dass die Dunkelläufer die Masse der Nightbane bilden und dass für jeden, der erschlagen wird, bald ein anderer seinen Platz einnimmt.]=],
		},
	},
})

Translate("deDE", "the-yorgen-farmstead", {
	title = "Yorgens Bauernhof",
	aliases = { "Yorgens Hof", "Svens Hof" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Yorgens Bauernhof liegt im Süden des Dämmerwalds. Er war das Zuhause von {link:sven-yorgen}Sven Yorgen{/link} und seiner Familie, bis die dunklen Reiter aus dem {link:deadwind-pass}Gebirgspass der Totenwinde{/link} kamen, während Sven fort war, und alle darin abschlachteten. Als Sven zurückkehrte, sah er eine schattenhafte Gestalt, die hinter einem alten Baumstumpf nahe der Scheune etwas vergrub. Was in dem Loch lag, war ein Tagebuch. Es erzählte von einem Bergmann, der aus {link:roland-s-doom}Rolands Verdammnis{/link} geflohen war, sich in der Scheune der Yorgens versteckt hatte und die Familie sterben sah.]=],
		},
	},
})

Translate("deDE", "vul-gol-ogre-mound", {
	title = "Ogerhort Vul'Gol",
	aliases = { "Vul'Gol" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Ogerhort Vul'Gol ist ein Gewirr von Höhlen im Süden des Dämmerwalds, gehalten von den {link:ogres}Ogern{/link} des Clans Splinter Fist. Ihre Krieger, Feuerweber und Zuchtmeister überfallen die Straßen und schleppen fort, was sie dort finden, sogar die Kiste eines alten Einsiedlers mit Kräutern und Werkzeug. Der Oger Zzarc'Vul haust im Hort. Er trägt ein großes Monokel, das ein Gelehrter aus {link:darkshire}Dunkelhain{/link} für seine eigenen Zwecke begehrt. Man glaubt, dass der Geist eines Wächters aus dem alten {link:raven-hill}Rabenflucht{/link} auf den Straßen nahe dem Hort umgeht, noch immer im Krieg mit den Ogern.]=],
		},
	},
})

Translate("deDE", "brightwood-grove", {
	title = "Schattenhain",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schattenhain ist ein Waldstück im {link:duskwood}Dämmerwald{/link}. Welche Helligkeit ihm auch einst seinen Namen gab, sie ist fort. Die {link:nightbane-worgen}Nightbane-Worgen{/link} jagen dort, ihre Schattenweber ziehen in Rudeln zwischen den Bäumen umher, und die Jäger von {link:darkshire}Dunkelhain{/link} sprechen den Namen des Hains mit bitterem Lachen aus. Wie der verlassene Obstgarten ist er ein Prüfungsgrund der {link:carevin-family}Familie Carevin{/link}. Wer sich dem Krieg der Carevins anschließen will, muss zuerst lebend aus seinen Schatten zurückkehren.]=],
		},
	},
})

Translate("deDE", "twilight-grove", {
	title = "Der Zwielichtshain",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Zwielichtshain liegt im Herzen des Dämmerwalds, nördlich der Straße, die den Wald durchquert. Dort erhebt sich ein großer Baum. Er ist einer der wenigen Orte in den {link:eastern-kingdoms}Östlichen Königreichen{/link}, an denen die wache Welt den {link:emerald-dream}Smaragdgrünen Traum{/link} berührt, das Reich, das die grünen Drachen hüten. Solche Tore sind selten auf der Welt, und die anderen liegen weit entfernt, im {link:the-hinterlands}Hinterland{/link} und in {link:kalimdor}Kalimdor{/link}. Niemand aus {link:darkshire}Dunkelhain{/link} spricht von dem Hain, und niemand behauptet zu wissen, warum ein solcher Ort in einem Wald der Toten liegen sollte.]=],
		},
	},
})

Translate("deDE", "tranquil-gardens-cemetery", {
	title = "Der Friedhof \"Stille Gärten\"",
	aliases = { "Stille Gärten" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Friedhof "Stille Gärten" liegt südlich von {link:darkshire}Dunkelhain{/link}, im Südosten des Dämmerwalds. Sein Name ist heute ein grausamer Scherz. Skelettkrieger und Skelettmagier wandeln zwischen seinen Gräbern, und ein wahnsinniger Ghul streift mit einem gestohlenen Spiegel über seine Wege. Er ist der dem Ort nächstgelegene Friedhof des Waldes. Seine Skelette tragen Faulblüten in ihren Schädeln, Blumen, aus denen der Wirt von Dunkelhain einen Schnaps braut, stark genug, um die Toten zu erwecken. Wenn sich dort die Toten erheben, hört die {link:the-night-watch}Nachtwache{/link} als Erste davon.]=],
		},
	},
})

Translate("deDE", "the-hushed-bank", {
	title = "Das stille Ufer",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das stille Ufer zieht sich am Fluss entlang des äußersten Westrands des Dämmerwalds. Hier hat {link:sven-yorgen}Sven Yorgen{/link} sein Lager mit seinem Gefährten Lars und einigen treuen Gefolgsleuten. Sie sind so wenige, dass keiner entbehrt werden kann, um Vorräte zu holen, also schickt ihnen {link:carevin-family}die Familie Carevin{/link} aus {link:darkshire}Dunkelhain{/link}, was sie kann. Sie leben von dem, was sie jagen können, und ausgehungerte Schreckenswölfe kommen aus den Wäldern herab, um ihnen jeden Bissen Fleisch streitig zu machen. Von diesem einsamen Ufer aus beobachtet Sven den Osten, wo der Nekromant {link:morbent-fel}Morbent Fel{/link} auf seinem Hügel wartet.]=],
		},
	},
})

Translate("deDE", "the-darkened-bank", {
	title = "Das dunkle Ufer",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das dunkle Ufer ist der lange Nordrand des Dämmerwalds, wo der Fluss zwischen dem Wald und den Ausläufern von {link:elwynn-forest}Elwynn{/link} fließt. Giftweberspinnen nisten an seinem Ufer, und der Koch der Scarlet Raven schätzt ihre Beine für seine Kuchen. {link:the-night-watch}Wächter{/link} patrouillieren die nahe Nordstraße, und einer von ihnen hütet das Stück gleich vor dem Ort. An dieser Straße hat ein Goblinhändler seinen Stand neben einem einsamen Wächter und verkauft seltene Waren an jeden, der die Reise wagt.]=],
		},
	},
})

Translate("deDE", "beggar-s-haunt", {
	title = "Bettlerschlupfwinkel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Bettlerschlupfwinkel liegt im äußersten Osten des Dämmerwalds, nahe der Grenze zum {link:deadwind-pass}Gebirgspass der Totenwinde{/link}. Die {link:forsaken}Verlassenen{/link} haben dort ein verborgenes Lager errichtet. Ihre Expedition wurde auf Befehl von {link:varimathras}Varimathras{/link} nach Süden geschickt, um die Länder des alten Königreichs {link:azeroth}Azeroth{/link} zu erkunden. Ein Apotheker der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link} arbeitet dort mit einem Todespirscher. Als ein menschlicher Spion gefasst wurde, der ihr Lager beobachtete, waren es die {link:orcs}Orcs{/link} von {link:stonard}Stonard{/link}, die ihn festnahmen, und die Verlassenen brannten darauf zu erfahren, was er wusste.]=],
		},
	},
})

Translate("deDE", "commander-althea-ebonlocke", {
	title = "Kommandantin Althea Ebonlocke",
	subtitle = "Anführerin der Nachtwache",
	found = "Dunkelhain, vor dem Rathaus",
	hint = [=[Sprecht mit der Kommandantin, die die Nachtwache von Dunkelhain anführt.]=],
	allegiance = "Die Nachtwache · Dunkelhain",
	aliases = { "Althea Ebonlocke", "Althea" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Althea Ebonlocke befehligt die {link:the-night-watch}Nachtwache{/link}, die Miliz, die {link:darkshire}Dunkelhain{/link} beschützt, seit die Soldaten Stormwinds fort sind. Sie ist streng und ungeduldig, und für Spuren, die ins Leere führen, hat sie keine Zeit. Ihre Wächter sind zu wenige für den Wald, den sie halten müssen. Sie bittet jeden Fremden um Hilfe, der sie zu geben bereit ist, und sie verschwendet seine Zeit nicht mit Förmlichkeiten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Das Volk von {link:darkshire}Dunkelhain{/link} verdankt ihr sein Überleben mehr als irgendjemandem sonst. Der Geschichtsschreiber des Ortes zählt sie zu den Helden, ohne die Dunkelhain gefallen wäre.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie hält {link:darkshire}Dunkelhain{/link} und seine Straßen mit einer Handvoll {link:the-night-watch}Wächter{/link}.
• Sie schickt Freiwillige gegen die Toten der Stillen Gärten und von {link:raven-hill}Rabenflucht{/link}.
• Sie beobachtete {link:stalvan-mistmantle}Stalvan Mistmantle{/link} jahrelang, seiner Schuld gewiss, aber unfähig, sie zu beweisen.
• Sie hat einige ihrer stärksten Wächter an den umherwandernden toten Ritter {link:mor-ladim}Mor'Ladim{/link} verloren.]=],
		},
	},
	chapters = {
		{
			title = "Die Toten des Dämmerwalds",
			hint = "Folgt dem Ruf der Kommandantin gegen die Untoten.",
			text = [=[Es begann mit den Skeletten der Stillen Gärten, gleich südlich des Ortes. Dann kamen die Berichte aus {link:raven-hill}Rabenflucht{/link}, wo die Toten noch dichter standen, und zuletzt aus dem östlichen Mausoleum des großen Friedhofs, wo die Seuchenverbreiter nisten. Jedes Mal hatte Althea keine {link:the-night-watch}Wächter{/link} übrig. Jedes Mal ging ein Fremder an ihrer Stelle.]=],
		},
		{
			title = "Der Beweis",
			hint = [=[Bringt der Kommandantin den Beweis, auf den sie lange gewartet hat.]=],
			text = [=[Jahrelang hatte sie {link:stalvan-mistmantle}Stalvan{/link} beobachtet und ihn nicht anrühren können. Als man ihr die Tagebuchseiten vorlegte und der Schreiber des Ortes schwor, dass die Handschrift mit dem Register übereinstimmte, brauchte sie keine Geduld mehr. Sie gab den Befehl, Stalvan hinzurichten.]=],
		},
		{
			title = "Der Ritter ohne Ruhe",
			hint = [=[Erfahrt von der Kommandantin das Schicksal von Morgan Ladimore.]=],
			text = [=[Der Untote, der sich {link:mor-ladim}Mor'Ladim{/link} nennt, hatte im ganzen Wald {link:humans}Menschen{/link} getötet und ihre Patrouillen niedergemacht. Als man ihr seinen Schädel brachte, dankte Althea. Dann gestand sie, was sie zuvor nicht gesagt hatte: dass die Tochter des toten Ritters eine ihrer eigenen Wächterinnen war.]=],
		},
	},
	mentions = {
