Translate("deDE", "abercrombie", {
	title = "Abercrombie",
	subtitle = "Der Einsiedler von Rabenflucht",
	found = "Eine Hütte am Nordrand des Friedhofs von Rabenflucht",
	hint = [=[Besucht den alten Einsiedler, der in einer Hütte über dem Friedhof von Rabenflucht lebt.]=],
	allegiance = "Keine",
	aliases = { "Der Einbalsamierer", "Einbalsamierer" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Abercrombie scheint ein gebrechlicher alter Mann zu sein, der allein in einer Hütte über dem {link:raven-hill-cemetery}Friedhof von Rabenflucht{/link} lebt. Den Weg in den Ort wagt er nicht mehr, und er bittet Vorbeikommende um kleine Gefallen: Garn, starken Schnaps, Ghulknochen für eine Vogelscheuche, eine an die {link:ogres}Oger{/link} verlorene Kiste. Er ist dankbar, und er lacht viel. Er ist auch der Einbalsamierer.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die Kinder von {link:darkshire}Dunkelhain{/link} kennen den Einbalsamierer aus einer Gutenachtgeschichte. Er war ein gütiger Alchemist, und als seine Frau {link:eliza}Eliza{/link} starb, trieb ihn die Trauer in den Wahnsinn. Er legte sein eigenes Herz in ihre Brust, um sie zurückzuholen. Sie erhob sich wieder, mit einem Hunger nach Menschenfleisch, und er musste sie begraben halten. Die Geschichte ist wahr, und der Einbalsamierer lebt neben ihrem Grab.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sammelte Garn aus Geisterhaar, Zombiesaft und Ghulrippen durch die Hände von Fremden.
• Er baute ein Geschöpf aus Fleisch, Knochen und Metall, um es gegen {link:darkshire}Dunkelhain{/link} zu schicken.
• Er schrieb dem Bürgermeister in einer Schrift, die niemand im Ort lesen konnte.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Der wahre Name des Einsiedlers, sein Alter und die Jahre seines Wahnsinns sind nirgends verzeichnet.]=],
		},
	},
	chapters = {
		{
			title = "Die Gefallen eines alten Mannes",
			hint = [=[Helft dem Einsiedler mit den Dingen, die er nicht selbst holen kann.]=],
			text = [=[Das Garn, sagte er, sei für seine Türen und Fenster, um Geister fernzuhalten. Der Saft sollte ihn in kalten Nächten wärmen. Die Rippen waren für eine Vogelscheuche gegen Ghule. Jedes Ding war für sich harmlos. Jedes floss in dasselbe Werk.]=],
		},
		{
			title = "Das Geschöpf vor der Tür",
			hint = "Erfahrt, was der Brief des Einsiedlers wirklich sagt.",
			text = [=[Übersetzt war der Brief eine Prahlerei. Abercrombie nannte sich einen Schöpfer. Sein neuestes Werk wartete vor seiner Hütte, zähneknirschend, bereit, auf sein Wort gegen {link:darkshire}Dunkelhain{/link} zu marschieren. Der Fremde, der ihm geholfen hatte, hatte es gebaut, ohne es zu wissen.]=],
		},
	},
	mentions = {
		{ text = "Der Einsiedler" },
		{ text = "Das Garn überbringen" },
		{ text = "Saftlieferung" },
		{ text = "Ghulisches Abbild" },
		{ text = "Ogerdiebe" },
		{ text = "Nachricht an den Bürgermeister" },
	},
	bonds = {
		{ id = "eliza", name = "Eliza", note = "seine Frau" },
		{ id = "stitches", name = "Stitches", note = "seine Schöpfung" },
		{ id = "lord-ello-ebonlocke", name = "Lord Ello Ebonlocke", note = "las seinen Brief" },
		{ id = "madame-eva", name = "Madame Eva", note = "fertigte sein Garn" },
	},
})

Translate("deDE", "eliza", {
	title = "Eliza",
	subtitle = "Braut des Einbalsamierers",
	found = [=[Ihr Grab neben der Hütte des Einsiedlers, über dem Friedhof von Rabenflucht]=],
	hint = "Findet das Grab, das neben der Hütte des Einsiedlers liegt.",
	allegiance = "Der Einbalsamierer",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Eliza war die Frau des Alchemisten, der zum {link:abercrombie}Einbalsamierer{/link} wurde. Als sie starb, konnte er sie nicht gehen lassen. Er gab ihr sein eigenes Herz, und sie erhob sich vom Tod. Was sich erhob, war nicht die Frau, die er geliebt hatte. Sie erwachte mit einem Hunger nach dem Fleisch der Lebenden, und ihr Mann begrub sie erneut, um die Welt vor ihr zu bewahren.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Eliza ist die Quelle der Macht des Einbalsamierers. Sein Herz schlägt noch immer in ihr, und solange es schlägt, hält seine dunkle Magie. Um ihn zu brechen, muss das Volk von {link:darkshire}Dunkelhain{/link} zuerst ihr Grab öffnen. Ihr Grab liegt in Sichtweite der Tür ihres Mannes. Was auch immer er sonst vergessen hat, der {link:abercrombie}Einbalsamierer{/link} hat sie nahe bei sich behalten.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie liegt in einem flachen Grab nahe der Hütte ihres Mannes, über dem {link:raven-hill-cemetery}Friedhof von Rabenflucht{/link}.
• Eigene Wachen verteidigen sie, wenn ihr Grab geöffnet wird.
• Sie bewahrt das Herz des Einbalsamierers in ihrer Brust.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Geschichte verzeichnet Elizas Leben vor ihrem Tod oder wie sie starb.]=],
		},
	},
	chapters = {
		{
			title = "Das geöffnete Grab",
			hint = "Grabt in dem Grab nahe der Hütte des Einsiedlers.",
			text = [=[Die Erde über dem Grab war locker, als wäre sie mehr als einmal ausgehoben und wieder aufgefüllt worden. Darunter lag ein Sarg, und aus seinem Inneren kamen das Kratzen von Klauen und das Mahlen fauliger Zähne. Als der Deckel geöffnet wurde, kam Eliza heraus. Das Herz wurde ihr noch schlagend genommen. Der Bürgermeister von {link:darkshire}Dunkelhain{/link} nannte es einen Schutz gegen das Böse des Wahnsinnigen, und er schwor, dass der Name dessen, der es brachte, für immer in den Annalen des Ortes bleiben würde.]=],
		},
	},
	mentions = {
		{ text = "Braut des Einbalsamierers" },
		{ text = "Im Dreck wühlen" },
	},
	bonds = {
		{ id = "abercrombie", name = "Abercrombie", note = "ihr Mann" },
		{ id = "lord-ello-ebonlocke", name = "Lord Ello Ebonlocke", note = "ließ nach dem Herzen ihres Mannes schicken" },
	},
})

Translate("deDE", "stalvan-mistmantle", {
	title = "Stalvan Mistmantle",
	subtitle = "Der Hauslehrer des Anwesens der Mistmantles",
	found = "Anwesen der Mistmantles, nördlich von Dunkelhain",
	hint = "Sucht das einsame Haus nördlich von Dunkelhain auf.",
	allegiance = "Keine",
	aliases = { "Stalvan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Stalvan Mistmantle kam aus dem {link:silverpine-forest}Silberwald{/link} und studierte bei Rektor Crillian an einer Akademie in {link:stormwind-city}Stormwind{/link}. Er wurde Lehrer von Kindern, zuerst in {link:moonbrook}Moonbrook{/link} und dann im Haus einer Adelsfamilie, der Flintridges. Dort verliebte er sich in seine Schülerin Tilloa. Als sie einen anderen wählte, wurde seine Liebe zu Hass. Ein Massaker im Haus der Flintridges folgte, und Stalvan zog sich allein in die Wälder über {link:darkshire}Dunkelhain{/link} zurück.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Stalvan ist die finsterste Legende des Dämmerwalds. Die Wahrheit über ihn lag jahrelang verborgen, in verstreuten Seiten, einem verlorenen Brief und der Erinnerung eines alten Marschalls von {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er leitete das neue Schulhaus von {link:moonbrook}Moonbrook{/link} und verließ es, als Unruhe über {link:westfall}Westfall{/link} kam.
• Er wurde Hauslehrer von Giles und Tilloa, den Kindern der Familie Flintridge.
• Er führte ein Tagebuch, das seine Liebe zu Tilloa und seinen Abstieg in die Raserei festhielt.]=],
		},
	},
	chapters = {
		{
			title = "Die Spur der Briefe",
			hint = [=[Folgt dem Namen Stalvan von Dunkelhain nach Moonbrook und Goldhain.]=],
			text = [=[Das Register des Ortes führte zwei Adressen für Stalvan. In {link:moonbrook}Moonbrook{/link} erzählte ein Brief, den er nie abschickte, von seiner Freude am Bau einer Schule. Im Lion's Pride Inn in {link:goldshire}Goldhain{/link} wartete ein weiterer, zurückgelassen von einem Boten, der in einer stürmischen Nacht floh. Darin bot Stalvan einem {link:house-of-nobles}Adelshaus{/link} seine Dienste als Hauslehrer an.]=],
		},
		{
			title = "Das Tagebuch",
			hint = "Sammelt die verstreuten Seiten von Stalvans Tagebuch.",
			text = [=[Die Seiten erzählen die Geschichte in seiner eigenen Handschrift. Er schrieb von Tilloas Schönheit, von einer Blume, die sie ihm in die Hand legte, von einem Sommer im Landhaus der Familie nahe dem {link:eastvale-logging-camp}Osttal{/link}. Dann schrieb er von Zorn, als sie ihn vor ihrem Verehrer einen netten alten Mann nannte, und von einer schwarzen Leere, die in ihm wuchs. Die letzte Seite verspricht Blut.]=],
		},
		{
			title = "Die Hinrichtung",
			hint = "Vollstreckt das Urteil der Nachtwache.",
			text = [=[Als der Schreiber von {link:darkshire}Dunkelhain{/link} die Handschrift des Tagebuchs mit dem Register abglich, hatte die {link:the-night-watch}Nachtwache{/link} ihren Beweis. Stalvan starb in seinem Haus, und sein Familienring wurde zu der Seherin gebracht, die ihn zuerst genannt hatte. Sie spürte, wie der Wald freier atmete.]=],
		},
	},
	mentions = {
		{ text = "Die Legende von Stalvan" },
		{ text = "Die Legende von Stalvan" },
		{ text = "Die Legende von Stalvan" },
		{ text = "Die Legende von Stalvan" },
	},
	bonds = {
		{ id = "marshal-haggard", name = "Marschall Haggard", note = "untersuchte das Massaker" },
		{ id = "madame-eva", name = "Madame Eva", note = "sah seinen Namen in einer Vision" },
		{ id = "commander-althea-ebonlocke", name = "Kommandantin Althea Ebonlocke", note = "befahl seinen Tod" },
		{ id = "clerk-daltry", name = "Schreiber Daltry", note = "glich seine Handschrift ab" },
	},
})

Translate("deDE", "mor-ladim", {
	title = "Mor'Ladim",
	subtitle = "Der Ritter ohne Ruhe",
	found = "Umherwandernd auf dem Friedhof von Rabenflucht",
	hint = [=[Stellt Euch dem toten Ritter, der über den Friedhof von Rabenflucht wandert.]=],
	allegiance = "Keine",
	aliases = { "Morgan Ladimore" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Morgan Ladimore war ein Ritter, der für die Unschuldigen und die Armen kämpfte. Mit achtzehn heiratete er ein Mädchen namens Lys, und sie hatten einen Sohn und zwei Töchter. Als der Krieg nach {link:lordaeron}Lordaeron{/link} kam, zog er nach Norden, um an der Seite von {link:uther-the-lightbringer}Uther dem Lichtbringer{/link} zu kämpfen. Er kehrte heim und fand seinen Wald verrottet und sein Haus in Trümmern. Nun wandelt er als Mor'Ladim über den Friedhof, ein totes Ding, das ohne Grund tötet.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Morgans Fall ist die traurigste Geschichte des Dämmerwalds. Er war ein guter Mann, von Trauer gebrochen. Sein Name ist eine Warnung davor, was die Dunkelheit des Waldes selbst dem stärksten Herzen antun kann.]=],
		},
		{
			title = "Taten",
			text = [=[• Er diente {link:uther-the-lightbringer}Uther{/link} durch den Krieg im Norden und sah, wie der Orden der Paladine aufgelöst, Uther erschlagen und die Seuche verbreitet wurde.
• Er durchsuchte jeden Hof und jedes Haus des Dämmerwalds nach seiner Familie.
• Auf dem {link:raven-hill-cemetery}Friedhof von Rabenflucht{/link} fand er einen Grabstein mit dem Namen seiner Frau.
• In seiner Trauer tötete er drei Friedhofswärter und nahm sich dann das Leben.]=],
		},
	},
	chapters = {
		{
			title = "Das verwitterte Grab",
			hint = [=[Sucht nach einem Grab am äußersten Rand des Friedhofs von Rabenflucht.]=],
			text = [=[Man begrub ihn hastig, ohne Riten, jenseits des Friedhofsrandes. Tage später war die Erde aufgewühlt, und das Grab war leer. Der Geschichtsschreiber von {link:darkshire}Dunkelhain{/link}, der {link:morgan-stern}Morgan{/link} vor dem Krieg gekannt hatte, verwahrt ein Buch, das seine Geschichte erzählt.]=],
		},
		{
			title = "Der Ring einer Tochter",
			hint = "Bringt dem Grab von Morgan Ladimore Trost.",
			text = [=[{link:morgan-stern}Morgan{/link} starb in dem Glauben, seine ganze Familie sei tot. Eine Tochter, Sarah, hatte überlebt. Als ihr Ring auf sein Grab gelegt wurde, erhob sich eine Stimme im Wind. Der Ritter sprach voller Staunen den Namen seiner Tochter, und die Last auf seiner Seele wurde gehoben. Er gab sein Schwert Archeus dem, der ihm Frieden gebracht hatte, und seine letzten Worte galten seiner Frau Lys.]=],
		},
	},
	mentions = {
		{ text = "Das verwitterte Grab" },
		{ text = "Morgan Ladimore" },
		{ text = "Mor'Ladim" },
		{ text = "Die Liebe einer Tochter" },
	},
	bonds = {
		{ id = "sarah-ladimore", name = "Sarah Ladimore", note = "seine Tochter" },
		{ id = "sirra-von-indi", name = "Sirra Von'Indi", note = "kannte ihn vor dem Krieg" },
		{ id = "commander-althea-ebonlocke", name = "Kommandantin Althea Ebonlocke", note = "jagte ihn" },
		{ id = "uther-the-lightbringer", name = "Uther der Lichtbringer", note = "der Paladin, dem er diente" },
	},
})

Translate("deDE", "sven-yorgen", {
	title = "Sven Yorgen",
	subtitle = "Rächer von Yorgens Bauernhof",
	found = "Sein Lager an der Westgrenze des Dämmerwalds",
	hint = [=[Findet den Bauern, der am äußersten Westrand des Waldes ein Lager hält.]=],
	allegiance = "Svens Lager",
	aliases = { "Sven" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sven Yorgen bewirtschaftete einst einen Hof im Süden des Dämmerwalds. Während er fort war, kamen schwarz gekleidete Reiter aus dem {link:deadwind-pass}Gebirgspass der Totenwinde{/link} und töteten seine Familie. Er verfolgte sie und verlor sie. Nun hält er mit einigen Gefolgsleuten ein Lager im Westen und lebt für einen einzigen Zweck: Rache an den dunklen Reitern und ihrem Verbündeten, dem Nekromanten {link:morbent-fel}Morbent Fel{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Das Ende des Nekromanten",
			hint = [=[Helft Sven, gegen den Nekromanten des verlassenen Guts zu schlagen.]=],
			text = [=[{link:morbent-fel}Morbent Fel{/link} war von Zaubern geschützt, die keine Klinge durchdringen konnte. Sven schickte nach {link:stormwind-city}Stormwind{/link} um Hilfe. Eine Waffe aus Lichtschmiedeeisen, geborgen aus einem gesunkenen Schiff von {link:kul-tiras}Kul Tiras{/link}, brach die Schutzzauber des Nekromanten. Als Fel fiel, wusste Sven, dass die dunklen Reiter noch frei waren. Es war ein kleiner Sieg, und er nahm ihn gerne an.]=],
		},
	},
	mentions = {
		{ text = "Svens Rache" },
		{ text = "Svens Lager" },
		{ text = "Rückkehr zu Sven" },
		{ text = "Auf der Suche nach Weisheit" },
		{ text = "{link:morbent-fel}Morbent Fel{/link}" },
	},
	bonds = {
		{ id = "morbent-fel", name = "Morbent Fel", note = "sein Feind" },
		{ id = "jitters", name = "Jitters", note = "sah seine Familie sterben" },
	},
})

Translate("deDE", "jitters", {
	title = "Jitters",
	subtitle = "Der Überlebende von Rolands Verdammnis",
	found = "Versteckt in einem Haus in Rabenflucht",
	hint = [=[Sucht den verängstigten Mann, der sich im Geisterdorf Rabenflucht versteckt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jitters war Bergmann in {link:roland-s-doom}Rolands Verdammnis{/link}. Sein Name kommt von seinen Nerven, und er glaubt, dass diese Nerven ihm das Leben gerettet haben. Er war es, der den Schaft einer Sense aus dem Geröll der Mine zog, und noch in derselben Nacht kamen die Worgen. Er floh, versteckte sich in {link:sven-yorgen}Sven{/link} Yorgens Scheune und sah, wie die dunklen Reiter Svens Familie töteten. Nun versteckt er sich im Geisterdorf {link:raven-hill}Rabenflucht{/link}, lebt von Maden und Unkraut und fürchtet den Tag, an dem Sven ihn findet.]=],
