		{
			title = "Bedeutung",
			text = [=[Jitters könnte der Mann sein, der die Worgen in den {link:duskwood}Dämmerwald{/link} brachte. Er fürchtet, dass er es ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er zog den Schaft einer Sense aus dem Geröll von {link:roland-s-doom}Rolands Verdammnis{/link}.
• Er versteckte sich in der Scheune der Yorgens und schrieb auf, was er dort sah.
• Er ließ die erste Hälfte seines Tagebuchs auf dem Hof vergraben zurück und behielt den Rest.]=],
		},
	},
	mentions = {
