		{ id = "sven-yorgen", name = "Sven Yorgen", note = "geschworen, ihn zu töten" },
		{ id = "dextren-ward", name = "Dextren Ward", note = "verkaufte ihm Leichen" },
	},
})

Translate("deDE", "stitches", {
	title = "Stitches",
	subtitle = "Geschenk des Einbalsamierers",
	found = "Die Straße von Rabenflucht nach Dunkelhain",
	hint = [=[Hütet Euch vor dem Geschöpf, das die Straße hinab nach Dunkelhain marschiert.]=],
	allegiance = "Der Einbalsamierer",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Stitches ist das Geschöpf des Einbalsamierers, gemacht aus Fleisch, Knochen und verbogenem Metall. Es wurde aus genau den Dingen gebaut, die ein Fremder zur Hütte des Einsiedlers brachte, und es wartete vor dieser Hütte auf das Wort seines Meisters. Als das Wort kam, marschierte es die Straße hinab nach {link:darkshire}Dunkelhain{/link}, um abzuschlachten, was es fand.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Stitches ist der Beweis, dass das alte Kindermärchen vom {link:abercrombie}Einbalsamierer{/link} wahr war und dass der Wahnsinnige nicht aufgehört hatte, Dinge zu erschaffen.]=],
		},
		{
			title = "Taten",
			text = [=[• Es wartete vor der Hütte des Einsiedlers auf das Wort seines Schöpfers.
• Es brach nach {link:darkshire}Dunkelhain{/link} auf, kurz nachdem der Brief des Einbalsamierers übersetzt worden war.]=],
		},
	},
	mentions = {
		{ text = "Übersetzung für Ello" },
	},
	bonds = {
		{ id = "abercrombie", name = "Abercrombie", note = "sein Schöpfer" },
	},
})

Translate("deDE", "avette-fellwood", {
	title = "Avette Fellwood",
	subtitle = "Bognerin von Dunkelhain",
	found = "Dunkelhain, an ihrem Bognerstand",
	hint = [=[Sucht die Bognerin von Dunkelhain, die einen Waisenjungen aufgenommen hat.]=],
	allegiance = "Dunkelhain",
	aliases = { "Avette" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Avette Fellwood ist eine Bognerin von {link:darkshire}Dunkelhain{/link}. Sie hat vor Kurzem Jeremy Heartweaver adoptiert, einen Jungen, der den Fall von {link:lordaeron}Lordaeron{/link} überlebte und in ein Waisenhaus in {link:stormwind-city}Stormwind{/link} gebracht wurde. Jeremy hat seit dem Angriff auf seine Stadt nicht mehr gesprochen. Sein Vater Edward erhob sich unter den {link:forsaken}Verlassenen{/link} und durchsuchte jede Woche die Ruinen der {link:capital-city}Hauptstadt{/link} nach dem Leichnam seines Sohnes, bis er eines Tages nicht zurückkehrte. Sein letzter Brief, mit Blut befleckt, hat seinen Weg zu Avette gefunden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Avette entschied sich, den Jungen zu schützen, statt ihn zu verletzen. Sie wird ihm seine Vergangenheit nicht verbergen. Sie wird ihm den Brief seines Vaters geben, wenn er alt genug ist, ihn zu ertragen.]=],
		},
	},
	mentions = {
		{ text = "Vergiss nicht, dass ich dich liebe" },
	},
	bonds = {
		{ id = "ruins-of-lordaeron", name = "Ruinen von Lordaeron", note = "wo der Brief gefunden wurde" },
	},
})

Translate("deDE", "the-night-watch", {
	title = "Die Nachtwache",
	aliases = { "Nachtwache", "Wächter" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Nachtwache ist die Miliz von {link:darkshire}Dunkelhain{/link}. Sie wurde aufgestellt, als eine üble Magie in den {link:duskwood}Dämmerwald{/link} sickerte und {link:stormwind-city}Stormwind{/link} seine Wachen heimrief. Seither ist die Wache alles, was zwischen dem Ort und dem Wald steht. Sie wird von {link:commander-althea-ebonlocke}Kommandantin Althea Ebonlocke{/link} geführt, und ihre Mitglieder heißen Wächter.]=],
		},
		{
			title = "Die Wächter",
			text = [=[Wächter hüten die Tore und den Platz von {link:darkshire}Dunkelhain{/link}, und einige halten einsame Posten an den Straßen: zwei an der Weststraße, einer an der Nordstraße neben einem Goblinhändler. Sie sind zu wenige, und sie wissen es. Ihre Kommandantin kann sie nicht weit vom Ort fortschicken. Wenn sich die Toten auf den Friedhöfen erheben, muss sie Fremde bitten, an ihrer Stelle zu gehen. Der tote Ritter {link:mor-ladim}Mor'Ladim{/link} hat einige ihrer Stärksten getötet.]=],
		},
		{
			title = "Die Wache und die Welt",
			text = [=[{link:darkshire}Dunkelhain{/link} verlässt sich auf die Wache als sein einziges Heer. Als {link:magistrate-solomon}Magistrat Solomon{/link} aus {link:lakeshire}Seenhain{/link} {link:lord-ello-ebonlocke}Lord Ebonlocke{/link} um sie anflehte, lehnte der Bürgermeister ab: Würde die Wache ausrücken, fiele der Ort, bevor sie den Waldrand erreichte. Nicht jeder bewundert sie. Der Jäger {link:calor}Calor{/link} verließ die Wache für {link:carevin-family}die Familie Carevin{/link} und nannte sie selbstgefällig. Unter den Wächtern sind {link:sarah-ladimore}Sarah Ladimore{/link}, Tochter eines gefallenen Ritters, und, in den Erzählungen von {link:raven-hill}Rabenflucht{/link}, der Bogenschütze Merrick Valor.]=],
		},
	},
})

Translate("deDE", "nightbane-worgen", {
	title = "Nightbane-Worgen",
	aliases = { "Nightbane" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Nightbane sind die {red:worgen}Worgen{/red} des Dämmerwalds: große Wolfsmenschen, die in Rudeln die südliche Hälfte des Waldes bejagen. Schattenweber und Dunkelläufer streifen durch den {link:brightwood-grove}Schattenhain{/link} und den verlassenen Obstgarten. Die Stärksten von ihnen, die üblen Fänge und die Verderbten, unterhalten ihre Feuer nahe den Höhlen des Südens und in der Mine von {link:roland-s-doom}Rolands Verdammnis{/link}.]=],
		},
		{
			title = "Ihr Kommen",
			text = [=[Die Worgen waren nicht immer hier. Die Jäger von {link:darkshire}Dunkelhain{/link} sagen, sie seien wie aus dem Nichts erschienen, und die ersten fand man in {link:roland-s-doom}Rolands Verdammnis{/link}. Ein Bergmann jener Mine, der Mann namens {link:jitters}Jitters{/link}, erzählt, wie es geschah. Er fand den Schaft einer Sense in einem Geröllhaufen und zog ihn heraus. In jener Nacht kamen die Worgen aus jedem Loch und jedem Vorsprung der Stollen, und die meisten Bergleute starben. Auf seiner Flucht verlor er die Sense. Er weiß nicht, ob er es war, der die Wolfsmenschen in den {link:duskwood}Dämmerwald{/link} brachte, doch er fürchtet es.

Die Sense war die {red:scythe-of-elune}Sense von Elune{/red}. Eine Priesterin der {link:night-elves}Nachtelfen{/link}, Velinde Starsong, hatte sie in diese Wälder getragen, und ihr Schicksal erfuhr man in den Minen. Die {link:sentinels}Schildwachen{/link} von {link:darnassus}Darnassus{/link} waren beunruhigt, dass ein Geschenk ihrer Göttin die Hände ihrer Dienerinnen verlassen hatte.]=],
		},
		{
			title = "Der Krieg gegen sie",
			text = [=[Die {link:carevin-family}Familie Carevin{/link} und ihr Jäger {link:calor}Calor{/link} führen einen endlosen Krieg gegen die Nightbane. Jedes Rudel, das sie vernichten, wird bald ersetzt. Niemand in {link:darkshire}Dunkelhain{/link} weiß bisher, welche Macht sie anzieht.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage erklärt, wie die Sense die Worgen rief, oder ob die Nightbane mit den Worgen im {link:silverpine-forest}Silberwald{/link} verwandt sind.]=],
		},
	},
})

Translate("deDE", "the-valor-family", {
	title = "Die Familie Valor",
	aliases = { "Familie Valor" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Familie Valor waren die Verteidiger von {link:raven-hill}Rabenflucht{/link}, bevor es fiel. Ein in dem verwüsteten Dorf gefundener Band, {i}Erinnerungen an Valor{/i}, verzeichnet sie einen nach dem anderen. Sein Verfasser trauert um sie und gibt sich selbst die Schuld an ihrem Fehlen.]=],
		},
		{
			title = "Die Familie",
			text = [=[• {b}Lord Grant Valor.{/b} Das Oberhaupt der Familie und der Anführer von {link:raven-hill}Rabenflucht{/link}. Als die Dunkelheit in die Wälder kam, sammelte er als Erster die Dorfbewohner. Er hasste die Untoten mehr als jeden anderen Feind und patrouillierte selbst über die Friedhöfe. Eine schwere Wunde, die sie ihm zufügten, heilte nie ganz.
• {b}Lady Cassandra Valor.{/b} Seine Frau. Wenig ist über sie bekannt außer ihrer Liebe zu ihrer Familie.
• {b}Silvia Valor.{/b} Eine Wache von Rabenflucht, berühmt dafür, Banditen und Betrüger mit dem Schwert zu richten. Man sagt, sie habe die Höfe des Dämmerwalds nie im Stich gelassen.
• {b}Ira Valor.{/b} Als ihr Vater erkrankte, ging sie in den Wald, um Nahrung zu sammeln, und bald zog sie die dunklen Wälder dem Dorf vor. Verirrte Reisende erzählen von einem Schatten, der sie zurück zur Straße führt.
• {b}Merrick Valor.{/b} Der jüngste Sohn. Er trat der {link:the-night-watch}Nachtwache{/link} bei und hütete die Straßen mit seinem Bogen.]=],
		},
		{
			title = "Ihre Geister",
			text = [=[Die Valors verschwanden alle auf einmal. Nun wandeln ihre Geister durch den Wald, noch immer bei dem Werk, das sie im Leben taten: Grant unter den Skeletten des Friedhofs, Silvia nahe den Höfen, Ira in den Wäldern, Merrick auf den Straßen. {link:sirra-von-indi}Sirra Von'Indi{/link}, der Geschichtsschreiber von {link:darkshire}Dunkelhain{/link}, glaubt, dass ein gemeinsamer Kummer sie an diese Welt bindet.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Was den Valors widerfuhr und was ihre Geister festhält, ist noch nicht bekannt.]=],
		},
	},
})

Translate("deDE", "carevin-family", {
	title = "Familie Carevin",
	aliases = { "Carevins", "die Familie Carevin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Carevins sind ein Haus in {link:darkshire}Dunkelhain{/link}, das einen eigenen Krieg aufgenommen hat. Sie jagen Dämonen, Untote und alle, die ihnen helfen, und sie trauen niemandem, der ihrer Sache nicht hilft. Ihr Oberhaupt ist {link:jonathan-carevin}Jonathan Carevin{/link}. Sein Jäger {link:calor}Calor{/link}, einst bei der {link:the-night-watch}Nachtwache{/link}, führt den Kampf gegen die {link:nightbane-worgen}Nightbane-Worgen{/link}.]=],
		},
		{
			title = "Der Haushalt",
			text = [=[Elaine Carevin kümmert sich um die Bedürfnisse der Ausgestoßenen des Ortes. Sie schickt Vorräte zu {link:sven-yorgen}Sven Yorgen{/link} im Westen, den sie einen Mann nennt, der das Werk des Lichts tut, und sie sorgt sich um den alten Einsiedler, der nicht mehr zum Markt kommt. Scott Carevin verkauft Pilze auf dem Platz, und ein kleiner Junge, Benjamin, spielt nahe dem Haus.]=],
		},
		{
			title = "Die Carevins und die Wache",
			text = [=[Die Carevins stellen sich der {link:the-night-watch}Nachtwache{/link} nicht offen entgegen. Doch {link:calor}Calor{/link} macht aus seiner Verachtung für sie kein Geheimnis. Er träumt von einem Tag, an dem die Gefolgsleute der Carevins die Wächter an Zahl übertreffen.]=],
		},
	},
})
